#[test]
fn stage_a_a_non_empty_unparseable_keystore_is_refused_and_untouched() {
    let h = Host::new();
    std::fs::write(h.keystore(), br#"{"v":1,"wal"#).unwrap();
    std::fs::set_permissions(h.keystore(), std::fs::Permissions::from_mode(0o600)).unwrap();
    let r = h.first_start();
    assert_eq!(r.code, Some(72), "{}", r.stderr);
    assert!(r.stderr.contains("KEYSTORE_RESIDUE"));
    assert_eq!(std::fs::read(h.keystore()).unwrap(), br#"{"v":1,"wal"#);
    assert!(!h.p("credstore").exists());
    // Mode errors: refused too.
    std::fs::set_permissions(h.keystore(), std::fs::Permissions::from_mode(0o644)).unwrap();
    let r = h.first_start();
    assert_eq!(r.code, Some(71), "{}", r.stderr);
}

#[test]
fn stage_a_ts_traces_stop_an_automatic_new_identity() {
    // Each trace kind alone is enough.
    type Trace = (&'static str, Box<dyn Fn(&Host)>);
    let traces: Vec<Trace> = vec![
        (
            "home .CoNET-SI",
            Box::new(|h| std::fs::create_dir_all(h.p("home/someone/.CoNET-SI")).unwrap()),
        ),
        (
            "home CoNET-SI",
            Box::new(|h| std::fs::create_dir_all(h.p("home/other/CoNET-SI")).unwrap()),
        ),
        (
            "root home",
            Box::new(|h| std::fs::create_dir_all(h.p("rootHome/.CoNET-SI")).unwrap()),
        ),
        (
            "conet.service",
            Box::new(|h| std::fs::write(h.p("units/conet.service"), b"[Unit]\n").unwrap()),
        ),
        (
            "enablement link",
            Box::new(|h| {
                std::fs::create_dir_all(h.p("units/multi-user.target.wants")).unwrap();
                std::os::unix::fs::symlink(
                    "../conet.service",
                    h.p("units/multi-user.target.wants/conet.service"),
                )
                .unwrap();
            }),
        ),
        (
            "running TS process",
            Box::new(|h| {
                std::fs::create_dir_all(h.p("proc/4711")).unwrap();
                std::fs::write(
                    h.p("proc/4711/cmdline"),
                    b"node\0/usr/lib/node_modules/conet-mvp-si/dist/cli.js\0start\0",
                )
                .unwrap();
            }),
        ),
    ];
    for (what, make) in traces {
        let h = Host::new();
        make(&h);
        for init in [
            None,
            Some(json!({"version":1})),
            Some(json!({"version":1,"identity":{"mode":"auto"}})),
        ] {
            if let Some(i) = init {
                h.init(i);
            }
            let r = h.first_start();
            assert_eq!(r.code, Some(74), "{what}: {}{}", r.stdout, r.stderr);
            assert!(
                r.stderr.contains("ts_node_detected"),
                "{what}: {}",
                r.stderr
            );
            assert!(h.tree().is_empty(), "{what}: created {:?}", h.tree());
            assert!(h.log().is_empty());
        }
        // generate alone is not enough; the second confirmation is required.
        h.init(json!({"version":1,"identity":{"mode":"generate"}}));
        let r = h.first_start();
        assert_eq!(r.code, Some(74), "{what}");
        assert!(
            r.stderr
                .contains("ts_traces_need_confirm_generate_on_ts_host"),
            "{what}: {}",
            r.stderr
        );
        assert!(h.tree().is_empty());
        // Confirmed: it proceeds and says so loudly.
        h.init(
            json!({"version":1,"identity":{"mode":"generate","confirm_generate_on_ts_host":true}}),
        );
        let r = h.first_start();
        assert!(r.ok, "{what}: {}", r.stderr);
        assert!(
            r.stdout
                .contains("WARNING: NEW IDENTITY CREATED ON A HOST WITH CoNET-SI (TS) TRACES"),
            "{what}: {}",
            r.stdout
        );
    }
}

#[test]
fn stage_a_imports_the_ts_identity_through_the_original_service_account() {
    let (w, k, setup) = small_public();
    let h = Host::new();
    let home = h.p("home/tsuser/.CoNET-SI");
    std::fs::create_dir_all(&home).unwrap();
    let setup_path = home.join("nodeSetup.json");
    std::fs::write(&setup_path, &setup).unwrap();
    std::fs::set_permissions(&setup_path, std::fs::Permissions::from_mode(0o644)).unwrap();
    let mtime = std::fs::metadata(&setup_path).unwrap().modified().unwrap();
    h.init(json!({"version":1,"identity":{"mode":"ts-import","ts_service_account":"tsuser","expect_wallet":w,"expect_key_id":k}}));
    let r = h.first_start();
    assert!(r.ok, "{}{}", r.stdout, r.stderr);
    assert_eq!(field(&r.stdout, "source"), "ts-import");
    assert!(field(&r.stdout, "wallet").eq_ignore_ascii_case(&w));
    assert_eq!(field(&r.stdout, "keyId"), k);
    let line = h.log();
    assert!(
        line.contains(&format!(
            "LoadCredential=nodesetup:{}",
            setup_path.display()
        )),
        "{line}"
    );
    assert!(
        line.contains("--create ts-import")
            && line.contains("--expect-wallet")
            && line.contains("--expect-key-id")
    );
    assert_eq!(std::fs::read(&setup_path).unwrap(), setup);
    assert_eq!(
        std::fs::metadata(&setup_path).unwrap().modified().unwrap(),
        mtime
    );
    // Next boot: light path asserting the same public values; the TS file is not needed any more.
    std::fs::remove_file(&setup_path).unwrap();
    let r = h.first_start();
    assert!(r.ok, "{}", r.stderr);
    assert_eq!(field(&r.stdout, "source"), "existing");
    assert!(r.stdout.contains("check: light"));
    // Wrong expectation in init.json against the existing keystore: refused.
    h.init(json!({"version":1,"identity":{"mode":"ts-import","ts_service_account":"tsuser","expect_wallet":"0x00000000000000000000000000000000000000a1","expect_key_id":k}}));
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("existing_identity_differs_from_expected"),
        "{}",
        r.stderr
    );
}

#[test]
fn stage_a_ts_import_refuses_instead_of_generating_when_anything_is_off() {
    let (w, k, setup) = small_public();
    let id = |extra: Value| {
        let mut i = json!({"mode":"ts-import","ts_service_account":"tsuser","expect_wallet":w,"expect_key_id":k});
        i.as_object_mut()
            .unwrap()
            .extend(extra.as_object().unwrap().clone());
        json!({"version":1,"identity":i})
    };
    // missing file
    let h = Host::new();
    h.init(id(json!({})));
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("ts_setup_missing"),
        "{}",
        r.stderr
    );
    assert!(h.tree().is_empty());
    // group/other writable
    let home = h.p("home/tsuser/.CoNET-SI");
    std::fs::create_dir_all(&home).unwrap();
    let sp = home.join("nodeSetup.json");
    std::fs::write(&sp, &setup).unwrap();
    std::fs::set_permissions(&sp, std::fs::Permissions::from_mode(0o666)).unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("ts_setup_writable_by_others"),
        "{}",
        r.stderr
    );
    // a symlink
    std::fs::remove_file(&sp).unwrap();
    std::fs::write(h.p("tmp/real.json"), &setup).unwrap();
    std::os::unix::fs::symlink(h.p("tmp/real.json"), &sp).unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("ts_setup_not_regular"),
        "{}",
        r.stderr
    );
    // wrong owner: passwd says another uid owns the account
    std::fs::remove_file(&sp).unwrap();
    std::fs::write(&sp, &setup).unwrap();
    std::fs::set_permissions(&sp, std::fs::Permissions::from_mode(0o644)).unwrap();
    let uid = std::fs::metadata(&sp).unwrap().uid_();
    std::fs::write(
        h.p("etc/passwd"),
        format!(
            "tsuser:x:{}:1::{}:/bin/sh\n",
            uid + 1,
            h.p("home/tsuser").display()
        ),
    )
    .unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("ts_setup_wrong_owner"),
        "{}",
        r.stderr
    );
    // unknown account
    std::fs::write(h.p("etc/passwd"), "nobody:x:1:1::/nonexistent:/bin/false\n").unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("ts_account_unknown"),
        "{}",
        r.stderr
    );
    assert!(
        h.tree().is_empty(),
        "something was created on a refused import: {:?}",
        h.tree()
    );
    // corrupt content passes the file checks but the sealing stage refuses; still no new identity
    let h = Host::new();
    h.init(id(json!({})));
    let home = h.p("home/tsuser/.CoNET-SI");
    std::fs::create_dir_all(&home).unwrap();
    std::fs::write(home.join("nodeSetup.json"), &setup[..setup.len() / 3]).unwrap();
    let r = h.first_start();
    assert!(!r.ok, "{}", r.stdout);
    assert!(
        r.stderr.contains("ts_import_refused:not_json"),
        "{}",
        r.stderr
    );
    assert!(
        !h.keystore().exists(),
        "a corrupt TS setup led to a generated identity"
    );
    // wrong expected public values
    let h = Host::new();
    h.init(json!({"version":1,"identity":{"mode":"ts-import","ts_service_account":"tsuser","expect_wallet":"0x00000000000000000000000000000000000000a1","expect_key_id":k}}));
    let home = h.p("home/tsuser/.CoNET-SI");
    std::fs::create_dir_all(&home).unwrap();
    std::fs::write(home.join("nodeSetup.json"), &setup).unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("wallet_mismatch"),
        "{}",
        r.stderr
    );
    assert!(!h.keystore().exists());
}

#[test]
fn stage_a_a_ts_import_refused_while_sealing_leaves_the_kek_which_the_rerun_reuses() {
    let (w, k, setup) = small_public();
    let h = Host::new();
    let import = |expect_wallet: &str| {
        h.init(json!({"version":1,"identity":{"mode":"ts-import","ts_service_account":"tsuser","expect_wallet":expect_wallet,"expect_key_id":k}}));
    };
    import("0x00000000000000000000000000000000000000a1");
    let home = h.p("home/tsuser/.CoNET-SI");
    std::fs::create_dir_all(&home).unwrap();
    std::fs::write(home.join("nodeSetup.json"), &setup).unwrap();
    let r = h.first_start();
    assert!(
        !r.ok && r.stderr.contains("wallet_mismatch"),
        "{}",
        r.stderr
    );
    assert!(!h.keystore().exists());
    assert!(h.kek().is_file(), "the KEK made before the refused stage");
    assert_eq!(std::fs::read(home.join("nodeSetup.json")).unwrap(), setup);
    let kek = std::fs::read(h.kek()).unwrap();
    import(&w);
    let r = h.first_start();
    assert!(r.ok, "{}", r.stderr);
    assert!(r.stdout.contains("kek: present"), "{}", r.stdout);
    assert_eq!(std::fs::read(h.kek()).unwrap(), kek, "the KEK was replaced");
    assert!(h.keystore().is_file());
    assert_eq!(std::fs::read(home.join("nodeSetup.json")).unwrap(), setup);
}

#[test]
fn stage_a_a_damaged_or_secret_bearing_init_json_refuses_before_anything_is_created() {
    let h = Host::new();
    let cases: Vec<(&[u8], &str)> = vec![
        (br#"{"version":1,"http_po"#, "init_config:not_json"),
        (br#"{"version":2}"#, "init_config:bad_value:version"),
        (
            br#"{"version":1,"passwd":"correct-horse"}"#,
            "init_config:secret_field_not_allowed:passwd",
        ),
        (
            br#"{"version":1,"identity":{"privateKey":"x"}}"#,
            "init_config:unknown_key:identity.privateKey",
        ),
        (
            br#"{"version":1,"identity":{"mode":"ts-import"}}"#,
            "init_config:identity.ts_import_needs_source",
        ),
    ];
    for (bytes, want) in cases {
        std::fs::write(h.p("etc/init.json"), bytes).unwrap();
        let r = h.first_start();
        assert_eq!(r.code, Some(74), "{want}: {}", r.stderr);
        assert!(r.stderr.contains(want), "{want}: {}", r.stderr);
        assert!(!r.stderr.contains("correct-horse"));
        assert!(h.tree().is_empty() && h.log().is_empty(), "{want}");
    }
    // Unreadable file is not "absent".
    std::fs::write(h.p("etc/init.json"), br#"{"version":1}"#).unwrap();
    std::fs::set_permissions(h.p("etc/init.json"), std::fs::Permissions::from_mode(0o666)).unwrap();
    let r = h.first_start();
    assert!(!r.ok && r.stderr.contains("writable_by_group_or_others"));
    assert!(h.tree().is_empty());
}

#[test]
fn stage_a_ts_price_fields_are_accepted_and_reported_as_ignored() {
    let h = Host::new();
    h.init(
        json!({"version":1,"storage_price":0.01,"outbound_price":0.00001,"cpus":8,"ipV6Port":80}),
    );
    let r = h.first_start();
    assert!(r.ok, "{}", r.stderr);
    for f in ["storage_price", "outbound_price", "cpus", "ipV6Port"] {
        assert!(
            r.stdout
                .contains(&format!("ignored: {f} (no Rust consumer)")),
            "{f}: {}",
            r.stdout
        );
    }
    // Nothing about them reaches the sealing stage.
    let line = h.log();
    assert!(!line.contains("price") && !line.contains("0.01"));
}

#[test]
fn stage_a_two_first_starts_at_once_share_one_kek_and_one_identity() {
    for round in 0..4 {
        let h = Host::new();
        let gate = h.p("tmp/gate");
        let n = 4;
        let kids: Vec<_> = (0..n)
            .map(|_| {
                let c = h.first_start_cmd();
                let prog = c.get_program().to_string_lossy().into_owned();
                let args: Vec<String> = c
                    .get_args()
                    .map(|a| a.to_string_lossy().into_owned())
                    .collect();
                let mut sh = Command::new("/bin/sh");
                sh.arg("-c")
                    .arg(format!(
                        "while [ ! -e '{}' ]; do :; done; exec \"$0\" \"$@\"",
                        gate.display()
                    ))
                    .arg(prog)
                    .args(args)
                    .env("FAKE_LOG", h.p("tmp/log"))
                    .env("FAKE_TMP", h.p("tmp"))
                    .env_remove("CREDENTIALS_DIRECTORY")
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped());
                sh.spawn().unwrap()
            })
            .collect();
        std::fs::write(&gate, b"go").unwrap();
        let outs: Vec<_> = kids
            .into_iter()
            .map(|k| k.wait_with_output().unwrap())
            .collect();
        let mut ids = std::collections::BTreeSet::new();
        for o in &outs {
            let so = String::from_utf8_lossy(&o.stdout).to_string();
            assert!(
                o.status.success(),
                "round {round}: {}",
                String::from_utf8_lossy(&o.stderr)
            );
            ids.insert((field(&so, "wallet"), field(&so, "keyId")));
        }
        assert_eq!(
            ids.len(),
            1,
            "round {round}: more than one identity announced"
        );
        assert_eq!(
            h.tree(),
            vec!["credstore/conet-node-kek", "state/keystore.json"],
            "round {round}"
        );
        // The keystore opens with the one KEK that was published.
        let kek_bytes = std::fs::read(h.kek()).unwrap();
        let k: [u8; 32] = kek_bytes.try_into().unwrap();
        keystore::open(&k, &std::fs::read_to_string(h.keystore()).unwrap()).unwrap();
    }
}

