#[test]
fn a_kek_race_loser_drops_its_own_credential_and_adopts_the_published_one() {
    let d = tempfile::tempdir().unwrap();
    let cred = d.path().join("credstore/conet-node-kek");
    std::fs::create_dir(d.path().join("credstore")).unwrap();
    // While this process "encrypts", another first start publishes its credential first.
    let winner = cred.clone();
    let created = first_start::ensure_kek(&cred, first_start::PathState::Absent, &move |_plain| {
        assert_eq!(
            atomic::publish_new(&winner, b"WINNER-CREDENTIAL").unwrap(),
            atomic::Published::Created
        );
        Ok(b"LOSER-CREDENTIAL".to_vec())
    })
    .unwrap();
    assert!(!created, "the loser claims to have created the credential");
    assert_eq!(std::fs::read(&cred).unwrap(), b"WINNER-CREDENTIAL");
    assert_eq!(
        std::fs::read_dir(d.path().join("credstore"))
            .unwrap()
            .count(),
        1,
        "a temp or second file is left"
    );
}

#[test]
fn encrypt_failures_create_nothing() {
    let d = tempfile::tempdir().unwrap();
    let cred = d.path().join("conet-node-kek");
    for bin in ["/nonexistent/systemd-creds", "/usr/bin/false"] {
        let r = first_start::ensure_kek(&cred, first_start::PathState::Absent, &|p| {
            first_start::encrypt_with_systemd_creds(bin, p)
        });
        assert!(r.is_err());
        assert!(!cred.exists());
    }
    // A credential command that prints nothing is a failure too.
    let sh = d.path().join("silent");
    std::fs::write(&sh, "#!/bin/sh\ncat >/dev/null\n").unwrap();
    std::fs::set_permissions(&sh, std::fs::Permissions::from_mode(0o755)).unwrap();
    let r = first_start::ensure_kek(&cred, first_start::PathState::Absent, &|p| {
        first_start::encrypt_with_systemd_creds(sh.to_str().unwrap(), p)
    });
    assert!(r.is_err() && !cred.exists());
}

#[test]
fn the_systemd_run_arguments_carry_no_secret_and_every_value_is_its_own_element() {
    let d = Path::new("/var/lib/conet-signer");
    let kek = Path::new("/etc/credstore.encrypted/conet-node-kek");
    let exe = Path::new("/usr/lib/conet-node/conet-signer");
    let ks = d.join("keystore.json");
    let a = first_start::StageA {
        init_config: Path::new("/etc/conet-node/init.json"),
        keystore: &ks,
        kek_credential: kek,
        exe,
        systemd_run: "systemd-run",
        systemd_creds: "systemd-creds",
        ts_home_base: Path::new("/home"),
        ts_root_home: Path::new("/root"),
        ts_unit_dirs: &[],
        proc_dir: Path::new("/proc"),
        passwd: Path::new("/etc/passwd"),
    };
    let expect = (
        "0x00000000000000000000000000000000000000a1".to_string(),
        "0123456789ABCDEF".to_string(),
    );
    let v = first_start::systemd_run_args(
        &a,
        "ts-import",
        Some(Path::new("/home/tsuser/.CoNET-SI/nodeSetup.json")),
        Some(&expect),
    );
    assert!(
        v.contains(&"LoadCredential=nodesetup:/home/tsuser/.CoNET-SI/nodeSetup.json".to_string())
    );
    assert!(v.contains(
        &"LoadCredentialEncrypted=conet-node-kek:/etc/credstore.encrypted/conet-node-kek"
            .to_string()
    ));
    assert!(
        v.contains(&"NoNewPrivileges=yes".to_string())
            && v.contains(&"RuntimeMaxSec=120".to_string())
    );
    let i = v
        .iter()
        .position(|x| x == "/usr/lib/conet-node/conet-signer")
        .unwrap();
    assert_eq!(
        &v[i + 1..i + 5],
        [
            "first-start-seal",
            "--keystore",
            "/var/lib/conet-signer/keystore.json",
            "--create"
        ]
    );
    assert!(v
        .iter()
        .all(|x| !x.contains("passwd") && !x.contains("PRIVATE")));
    // No setup credential for generate or reuse.
    let v = first_start::systemd_run_args(&a, "generate", None, None);
    assert!(!v.iter().any(|x| x.contains("nodesetup")));
}

#[test]
fn exit_codes_are_fixed_and_distinct() {
    let code = |s: &str| first_start::FirstStartError(s.into()).exit_code();
    assert_eq!(code("KEYSTORE_PRESENT_KEK_MISSING:credential_absent"), 70);
    assert_eq!(code("KEYSTORE_UNREADABLE:mode"), 71);
    assert_eq!(code("KEYSTORE_RESIDUE:not_a_keystore"), 72);
    assert_eq!(code("KEK_UNDECRYPTABLE:format"), 73);
    assert_eq!(code("ts_node_detected:x"), 74);
}

#[test]
fn rotate_route_still_replaces_the_keystore_atomically_with_a_unique_temp_name() {
    let state = private_dir();
    let kd = tempfile::tempdir().unwrap();
    let (kek, kek_hex) = kek_file(kd.path());
    let ks = state.path().join("keystore.json");
    let kg = run(bin().args([
        "keygen",
        "--insecure-kek-file",
        kek.to_str().unwrap(),
        "--keystore",
        ks.to_str().unwrap(),
    ]));
    assert!(kg.ok, "{}", kg.stderr);
    let before = std::fs::read(&ks).unwrap();
    let r = run(bin().args([
        "rotate-route",
        "--insecure-kek-file",
        kek.to_str().unwrap(),
        "--keystore",
        ks.to_str().unwrap(),
    ]));
    assert!(r.ok, "{}", r.stderr);
    assert_ne!(
        std::fs::read(&ks).unwrap(),
        before,
        "the rotation did not replace the keystore"
    );
    assert_eq!(
        names(state.path()),
        vec!["keystore.json"],
        "a temporary file was left"
    );
    assert_eq!(
        std::fs::metadata(&ks).unwrap().permissions().mode() & 0o777,
        0o600
    );
    let secrets = open_ks(state.path(), &kek_hex);
    assert!(
        !secrets.previous_pgp_armored.is_empty(),
        "the old route key must remain until retired"
    );
}
